# Add CSS only
$css='<style>.video-player-window{position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);z-index:10001;width:750px;background-color:#c0c0c0;border:2px solid #fff;border-right-color:#808080;border-bottom-color:#808080;padding:2px;box-shadow:4px 4px 10px rgba(0,0,0,0.5);font-family:Tahoma,sans-serif;display:flex;flex-direction:column}.video-player-header{background:linear-gradient(to right,#000080,#1084d0);color:white;padding:4px 8px;font-weight:bold;font-size:13px;display:flex;justify-content:space-between;align-items:center;margin-bottom:2px;cursor:grab}.video-player-close{width:16px;height:16px;background-color:#c0c0c0;border:1px solid #fff;border-right-color:#808080;border-bottom-color:#808080;cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:10px;font-weight:bold;color:black}.video-player-close:active{border:1px solid #808080;border-right-color:#fff;border-bottom-color:#fff}.video-player-body{display:flex;gap:4px;padding:4px}.video-main-area{flex:1;display:flex;flex-direction:column}#video-element{width:100%;height:300px;background-color:#000;border:2px solid #808080;border-right-color:#fff;border-bottom-color:#fff;margin-bottom:4px}.video-playlist{width:220px;background-color:#fff;border:2px solid #808080;border-right-color:#fff;border-bottom-color:#fff;overflow-y:auto;height:380px;font-size:11px}.playlist-item{padding:4px;cursor:pointer;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;border-bottom:1px dotted #ccc}.playlist-item:hover{background-color:#e0e0e0}.playlist-item.active{background-color:#000080;color:white}.video-controls-area{margin-top:4px;border:1px solid #fff;border-right-color:#808080;border-bottom-color:#808080;padding:4px;background-color:#c0c0c0}.seek-bar-container{height:15px;background-color:#000;margin-bottom:4px;position:relative;cursor:pointer;border:1px solid #808080;border-right-color:#fff;border-bottom-color:#fff}.seek-bar-fill{height:100%;background-color:#00ff00;width:0%}.control-buttons{display:flex;align-items:center;gap:4px}.retro-btn{width:24px;height:24px;background-color:#c0c0c0;border:1px solid #fff;border-right-color:#808080;border-bottom-color:#808080;cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:10px}.retro-btn:active{border:1px solid #808080;border-right-color:#fff;border-bottom-color:#fff;transform:translate(1px,1px)}.time-display{font-family:Courier New,monospace;font-size:11px;margin-left:auto;background:#000;color:#00ff00;padding:2px 4px;border:1px solid #808080;border-right-color:#fff;border-bottom-color:#fff}</style>'
$content=Get-Content "C:\Users\akoda\Documents\GitHub\my-website\index.html" -Raw
$content=$content -replace '(</head>)',"$css`r`n`$1"
Set-Content "C:\Users\akoda\Documents\GitHub\my-website\index.html" -Value $content -NoNewline
Write-Host "CSS added!" -ForegroundColor Green
